import dataclasses

@dataclasses.dataclass
class TranscriptionRequest:
    audio_file_uri: str
    language_code: str = "en-US"
    job_name: str = ""

@dataclasses.dataclass
class TranscriptionResult:
    job_name: str
    status: str
    transcript_uri: str = ""
    transcript_text: str = ""
    segments: list = dataclasses.field(default_factory=list)

